using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class StepOut
{
    public long lo { get; set; }
    public long hi { get; set; }
    public long cnt { get; set; }
}

public class Bisect : IAgentComputation
{
    const ulong MOD = 2147483647UL;
    const long K = 5000000L;
    const ulong M = 16777216UL;

    static long CountRange(ulong from, ulong to, double mid)
    {
        long cnt = 0;
        for (ulong i = from; i <= to; i++)
        {
            ulong z = i * 0x9E3779B97F4A7C15UL;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            z = z ^ (z >> 31);
            ulong r = z % MOD;
            double v = (double)r / 2147483647.0;
            if (v <= mid) cnt++;
        }
        return cnt;
    }

    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        string fstr;
        bool final = input.Parameters.TryGetValue("final", out fstr) && fstr == "true";
        int step = int.Parse(input.Parameters["step"]);

        double lo = 0.0, hi = 1.0;
        long total = 0;

        if (step > 1)
        {
            var prev = input.GetPreviousOutputs();
            bool first = true;
            foreach (var s in prev)
            {
                if (s == null) continue;
                var o = JsonSerializer.Deserialize<StepOut>(s);
                if (first) { lo = BitConverter.Int64BitsToDouble(o.lo); hi = BitConverter.Int64BitsToDouble(o.hi); first = false; }
                total += o.cnt;
            }
            // apply the previous step's update
            double pmid = (lo + hi) / 2.0;
            if (total >= K) hi = pmid; else lo = pmid;
        }

        if (final)
        {
            double fm = (lo + hi) / 2.0;
            return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new {
                step = step,
                mid = fm,
                midStr = fm.ToString("R", CultureInfo.InvariantCulture),
                midBits = BitConverter.DoubleToInt64Bits(fm),
                lo = lo,
                hi = hi,
                count = total
            })));
        }

        double mid = (lo + hi) / 2.0;
        int W = input.TotalWorkers;
        int w = input.WorkerIndex;
        ulong from = (ulong)w * M / (ulong)W + 1;
        ulong to = (ulong)(w + 1) * M / (ulong)W;
        long cnt = from <= to ? CountRange(from, to, mid) : 0;

        var res = new StepOut { lo = BitConverter.DoubleToInt64Bits(lo), hi = BitConverter.DoubleToInt64Bits(hi), cnt = cnt };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(res)));
    }
}

